"""Offline manifest/report generation from a completed 87-page crawl and read-only SQL snapshots."""
import csv,json,collections,datetime,sys
from discover import ROOT,CACHE,ARCHIVES
from parser import parse,match_existing
OUT=ROOT/'docs/migration'
def audit():
 discovery=json.loads((CACHE/'discovery.json').read_text());index=json.loads((CACHE/'crawl-index.json').read_text())
 if discovery['unique_count']!=87 or set(discovery['urls'])!={i['url'] for i in index} or len(index)!=87:raise SystemExit('STOP: discovery/crawl count gate not satisfied')
 before=json.loads((CACHE/'before.json').read_text());after=json.loads((CACHE/'after.json').read_text())
 keys=['property_count','attachment_count','taxonomy','property_sha256','relationships']
 if any(before[k]!=after[k] for k in keys):raise SystemExit('STOP: WordPress snapshot changed; investigate before generating review artifacts')
 records=[];failures=[]
 for item in index:
  try:
   if item['status']!='ok':raise ValueError(item.get('error','Fetch failed'))
   records.append(parse((CACHE/item['cache']).read_text(),item['url']))
  except Exception as error:failures.append({'source_url':item['url'],'error':str(error)})
 if failures:raise SystemExit('STOP: parsing failures; manifests not replaced: '+json.dumps(failures))
 match_existing(records,before)
 counts=collections.Counter(r['proposed_wp_slug'] for r in records)
 for r in records:
  if counts[r['proposed_wp_slug']]>1:r['warnings'].append('proposed_slug_collision')
  # Never collapse distinct source pages. Exact duplicates would have failed the discovery set gate.
  if r['existing_wp_post_id'] and r['sale_price'] is not None:
   r['warnings'].append('existing_wp_pricing_review');r['warning_details'].append({'code':'existing_wp_pricing_review','detail':'Source pricing is preserved for audit only. Review existing local price-suppression policy before any later import.'})
 source_counts=collections.Counter(r['source_category'] or 'Unknown' for r in records);tx_counts=collections.Counter(r['transaction_type_candidate'] or 'Unknown / ambiguous' for r in records);warnings=collections.Counter(w for r in records for w in r['warnings'])
 coverage={key:sum(r.get(key) is not None and r.get(key)!=[] for r in records) for key in ['source_title','source_category','source_author','source_publish_date','property_type','transaction_type_candidate','address_line_1','city','postal_code','building_sf','available_sf','minimum_available_sf','maximum_contiguous_sf','lot_acres','year_built','renovated_year','building_class','stories','clear_height_ft','parking_spaces','parking_ratio','traffic_count_vpd','sale_price','lease_rate_display','featured_image_url','brochure_url','property_highlights','suite_candidates']}
 summary={'discovered':87,'parsed':len(records),'failed':len(failures),'source_categories':dict(source_counts),'transaction_candidates':dict(tx_counts),'brochures':sum(bool(r['brochure_url']) for r in records),'properties_with_images':sum(r['image_count']>0 for r in records),'multiple_images':sum(r['image_count']>1 for r in records),'gallery_properties':sum(bool(r['gallery_images']) for r in records),'suite_properties':sum(bool(r['suite_candidates']) for r in records),'suite_candidates':sum(len(r['suite_candidates']) for r in records),'unparsed_availability_properties':sum(bool(r['unparsed_availability_blocks']) for r in records),'structured_pricing':sum(any(r[k] is not None for k in ['sale_price','lease_rate_min','lease_rate_max']) for r in records),'redirect_required':sum(r['redirect_required'] for r in records),'warnings':dict(warnings),'coverage':coverage,'existing_wp_matches':[{'source_url':r['source_url'],'post_id':r['existing_wp_post_id'],'method':r.get('existing_wp_match_method')} for r in records if r['existing_wp_post_id']]}
 stamp=datetime.datetime.now(datetime.timezone.utc).isoformat()
 manifest={'schema_version':1,'audit_only':True,'generated_at':stamp,'archive_pages':discovery['archives'],'status_policy':'All records need human review. Presence/publication date/author/category do not establish listing status. Authors are not listing brokers.','wordpress_unchanged':True,'wordpress_before_after':{k:{'before':before[k],'after':after[k]} for k in ['property_count','attachment_count','property_sha256']},'property_taxonomy_counts':[{'taxonomy':t['taxonomy'],'term':t['name'],'before':int(t['count']),'after':int(t['count'])} for t in before['taxonomy']],'taxonomy_snapshot_sha256':__import__('hashlib').sha256(json.dumps(before['taxonomy'],sort_keys=True).encode()).hexdigest(),'summary':summary,'records':records,'failures':failures}
 OUT.mkdir(parents=True,exist_ok=True);(OUT/'aspire-properties-manifest.json').write_text(json.dumps(manifest,indent=2,ensure_ascii=False)+'\n')
 columns=['source_title','source_url','source_category','proposed_wp_slug','existing_wp_post_id','property_type','transaction_candidate','city','postal_code','available_sf','building_sf','lot_acres','suite_count','image_count','has_brochure','redirect_required','warning_count','warnings','review_decision','review_notes']
 with (OUT/'aspire-properties-review.csv').open('w',newline='') as f:
  writer=csv.DictWriter(f,fieldnames=columns);writer.writeheader()
  for r in records:
   row={k:r.get(k) for k in columns};row.update(transaction_candidate=r['transaction_type_candidate'],suite_count=len(r['suite_candidates']),has_brochure=bool(r['brochure_url']),warning_count=len(r['warnings']),warnings='; '.join(r['warnings']),review_decision='',review_notes='')
   # Prevent formula interpretation if future source titles start with spreadsheet control characters.
   writer.writerow({k:('\''+v if isinstance(v,str) and v.startswith(('=','+','-','@','\t','\r')) else v) for k,v in row.items()})
 lines=['# Aspire legacy property dry-run audit','',f'Generated {stamp}. **No import performed.** All 87 records remain `needs_review`; this report does not establish active/current availability.','', '## Discovery and parsing','']
 lines += [f'- {p["url"]}: {p["property_links"]} unique links on that archive.' for p in discovery['archives']]
 lines += ['',f'Unique properties: **87**. Parsed: **{len(records)}**. Failed: **{len(failures)}**. URLs were discovered from links, not a hand-maintained list.','', '## Category and transaction counts','', '| Source category | Count |','|---|---:|']+[f'| {k} | {v} |' for k,v in sorted(source_counts.items())]
 lines += ['', '| Explicit transaction candidate | Count |','|---|---:|']+[f'| {k} | {v} |' for k,v in sorted(tx_counts.items())]
 lines += ['', '## Coverage','']+[f'- {label}: {summary[key]}/87 properties.' for key,label in [('brochures','Single brochure URL'),('properties_with_images','At least one property image'),('multiple_images','Multiple unique property images'),('gallery_properties','Gallery images'),('suite_properties','Suite candidates'),('unparsed_availability_properties','Unparsed availability blocks'),('structured_pricing','Normalized structured pricing'),('redirect_required','Legacy paths requiring a redirect')]]
 lines += [f'- Total suite candidates: {summary["suite_candidates"]}. No inferred suite availability statuses.','', '| Parsed field | Non-null records |','|---|---:|']+[f'| `{k}` | {v}/87 |' for k,v in coverage.items()]
 lines += ['', '## Existing prototype matches','']+[f'- WordPress {m["post_id"]}: {m["source_url"]} (`{m["method"]}`).' for m in summary['existing_wp_matches']]
 lines += ['', '## Warnings','', '| Code | Properties |','|---|---:|']+[f'| `{k}` | {v} |' for k,v in warnings.most_common()]
 lines += ['', '## Review recommendations','', '- Approve transaction intent and listing status manually before any future import. Missing transaction evidence stays null, even where the local prototype has a known transaction.', '- Confirm addresses marked ambiguous; malformed ZIPs and missing city/address components are not filled from local knowledge or geocoding.', '- Review all proposed slugs, especially the Pearland Parkway path containing embedded slashes. Preserve exact source URLs for the later redirect map.', '- Review Woodson’s mixed retail/medical/office rate and size ranges as separate availability contexts. Unparsed blocks are retained; the parser does not fabricate suite numbers or aggregate areas.', '- Reconcile the published FM 1093 $3,410,000 price with the existing local suppression policy before any future import. The manifest retains the source price; local records and frontend policy remain untouched.', '- Clay Road currently publishes 14-foot clear height but does not explicitly state a transaction in the parsed property body. Presidio contains a truncated building-size unit and a combined built/renovated label; uncertain values remain null.', '- Featured-image selection uses the first legitimate standalone property image where no reliable primary-image marker agrees. Every low-confidence choice is flagged; gallery assets are deduplicated by underlying URL while preserving order.', '- Source authors are audit provenance only and must never become listing advisors automatically.', '- Brochure and image URLs were recorded only. No PDFs/images were fetched or added to WordPress. No external scraping, geocoding or market-data service was used.','', '## Safety and reproducibility','', f'- Property count: {before["property_count"]} → {after["property_count"]}. Attachments: {before["attachment_count"]} → {after["attachment_count"]}.', '- Property taxonomy term rows/counts, relationships and complete property post/meta fingerprints match before/after.', '- Property taxonomy counts: '+', '.join(t['taxonomy']+'/'+t['slug']+': '+t['count']+' → '+t['count'] for t in before['taxonomy'])+'.', '- SQL snapshots use a direct read-only transaction, without bootstrapping WordPress. No application, schema, taxonomy or Docker edits.', '- HTML cache and SQL snapshots are Git-ignored under `var/migration/aspire-properties/`.', '- Run `python3 tools/migration/crawl.py` to reuse cached HTML; `--refresh` explicitly refreshes all fixed archives/property pages. The 87-page gate runs before property fetching/parsing.', '- Run the read-only snapshot command before and after the crawl, then `var/migration/venv/bin/python tools/migration/audit.py`. See the tool README for complete commands.', '- Network fetching uses system curl with TLS verification, a descriptive browser-style User-Agent, 45-second request timeout, two retries and a 0.75-second pause before each uncached request; requests are sequential.', '', '## Outputs','', '- `docs/migration/aspire-properties-manifest.json`', '- `docs/migration/aspire-properties-review.csv`', '- `docs/migration/aspire-properties-summary.md`', '']
 (OUT/'aspire-properties-summary.md').write_text('\n'.join(lines))
 print(json.dumps(summary,indent=2));return manifest
if __name__=='__main__':audit()
